def get_tops(self):
        '''
        Gather the top files
        '''
        tops = DefaultOrderedDict(list)
        include = DefaultOrderedDict(list)
        done = DefaultOrderedDict(list)
        found = 0  # did we find any contents in the top files?
        # Gather initial top files
        if self.opts['top_file_merging_strategy'] == 'same' and \
        not self.opts['environment']:
            if not self.opts['default_top']:
                raise SaltRenderError('Top file merge strategy set to same, but no default_top '
                          'configuration option was set')
            self.opts['environment'] = self.opts['default_top']

        if self.opts['environment']:
            contents = self.client.cache_file(
                self.opts['state_top'],
                self.opts['environment']
            )
            if contents:
                found = 1
                tops[self.opts['environment']] = [
                    compile_template(
                        contents,
                        self.state.rend,
                        self.state.opts['renderer'],
                        saltenv=self.opts['environment']
                    )
                ]
            else:
                tops[self.opts['environment']] = [{}]
        elif self.opts['top_file_merging_strategy'] == 'merge':
            found = 0
            if self.opts.get('state_top_saltenv', False):
                saltenv = self.opts['state_top_saltenv']
                contents = self.client.cache_file(
                    self.opts['state_top'],
                    saltenv
                )
                if contents:
                    found = found + 1
                    tops[saltenv].append(
                        compile_template(
                            contents,
                            self.state.rend,
                            self.state.opts['renderer'],
                            saltenv=saltenv
                        )
                    )
                else:
                    tops[saltenv].append({})
                    log.debug('No contents loaded for env: {0}'.format(saltenv))
            else:
                for saltenv in self._get_envs():
                    contents = self.client.cache_file(
                        self.opts['state_top'],
                        saltenv
                    )
                    if contents:
                        found = found + 1
                        tops[saltenv].append(
                            compile_template(
                                contents,
                                self.state.rend,
                                self.state.opts['renderer'],
                                saltenv=saltenv
                            )
                        )
                    else:
                        tops[saltenv].append({})
                        log.debug('No contents loaded for env: {0}'.format(saltenv))
            if found > 1:
                log.warning('Top file merge strategy set to \'merge\' and multiple top files found. '
                            'Top file merging order is undefined; '
                            'for better results use \'same\' option')

        if found == 0:
            log.error('No contents found in top file')

        # Search initial top files for includes
        for saltenv, ctops in six.iteritems(tops):
            for ctop in ctops:
                if 'include' not in ctop:
                    continue
                for sls in ctop['include']:
                    include[saltenv].append(sls)
                ctop.pop('include')
        # Go through the includes and pull out the extra tops and add them
        while include:
            pops = []
            for saltenv, states in six.iteritems(include):
                pops.append(saltenv)
                if not states:
                    continue
                for sls_match in states:
                    for sls in fnmatch.filter(self.avail[saltenv], sls_match):
                        if sls in done[saltenv]:
                            continue
                        tops[saltenv].append(
                            compile_template(
                                self.client.get_state(
                                    sls,
                                    saltenv
                                ).get('dest', False),
                                self.state.rend,
                                self.state.opts['renderer'],
                                saltenv=saltenv
                            )
                        )
                        done[saltenv].append(sls)
            for saltenv in pops:
                if saltenv in include:
                    include.pop(saltenv)
        return tops

